import heapq
from typing import List

class Solution:
    def minInterval(self, intervals: List[List[int]], queries: List[int]) -> List[int]:
        intervals.sort()
        res = [-1] * len(queries)
        pq = []
        i = 0
        for qi in sorted(range(len(queries)), key=queries.__getitem__):
            q = queries[qi]
            while i < len(intervals) and intervals[i][0] <= q:
                l, r = intervals[i]
                heapq.heappush(pq, (r - l + 1, r))
                i += 1
            while pq and pq[0][1] < q:
                heapq.heappop(pq)
            if pq:
                res[qi] = pq[0][0]
        return res
```

**Time/Space:** O((n + q) log n) / O(n + q)

**Pitfall:** Answers must be written back in the original query order.

**Pattern:** Transpose + reverse rows

**Key insight:** Clockwise rotation = transpose across the main diagonal, then mirror each row.

**Java**

```java
class Solution {
    public void rotate(int[][] m) {
        int n = m.length;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++) { int t = m[i][j]; m[i][j] = m[j][i]; m[j][i] = t; }
        for (int[] row : m)
            for (int l = 0, r = n - 1; l < r; l++, r--) { int t = row[l]; row[l] = row[r]; row[r] = t; }
    }
}
```

