from typing import List

class Solution:
    def spiralOrder(self, matrix: List[List[int]]) -> List[int]:
        res = []
        top, bot, left, right = 0, len(matrix) - 1, 0, len(matrix[0]) - 1
        while top <= bot and left <= right:
            res.extend(matrix[top][c] for c in range(left, right + 1))
            res.extend(matrix[r][right] for r in range(top + 1, bot + 1))
            if top < bot:
                res.extend(matrix[bot][c] for c in range(right - 1, left - 1, -1))
            if left < right:
                res.extend(matrix[r][left] for r in range(bot - 1, top, -1))
            top, bot, left, right = top + 1, bot - 1, left + 1, right - 1
        return res
```

**Time/Space:** O(m·n) / O(1) extra

**Pitfall:** Without the top<bot / left<right guards, a middle row or column gets added twice.

**Pattern:** Use first row/column as markers

**Key insight:** Record zero rows/cols in row 0 and col 0; track col 0's own state in a flag.

**Java**

```java
class Solution {
    public void setZeroes(int[][] m) {
        int R = m.length, C = m[0].length;
        boolean col0 = false;
        for (int r = 0; r < R; r++) {
            if (m[r][0] == 0) col0 = true;
            for (int c = 1; c < C; c++)
                if (m[r][c] == 0) { m[r][0] = 0; m[0][c] = 0; }
        }
        for (int r = R - 1; r >= 0; r--) {
            for (int c = C - 1; c >= 1; c--)
                if (m[r][0] == 0 || m[0][c] == 0) m[r][c] = 0;
            if (col0) m[r][0] = 0;
        }
    }
}
```

