from typing import List

class Solution:
    def setZeroes(self, matrix: List[List[int]]) -> None:
        R, C = len(matrix), len(matrix[0])
        col0 = False
        for r in range(R):
            if matrix[r][0] == 0:
                col0 = True
            for c in range(1, C):
                if matrix[r][c] == 0:
                    matrix[r][0] = matrix[0][c] = 0
        for r in range(R - 1, -1, -1):
            for c in range(C - 1, 0, -1):
                if matrix[r][0] == 0 or matrix[0][c] == 0:
                    matrix[r][c] = 0
            if col0:
                matrix[r][0] = 0
